presets.script:
if target.template == "servant":
    target.mp += 2 * this.mp_spent
else:
    target.mp += this.mp_spent

if reacting and level >= 1 and level > opp_level:
    self.negate()
    target.damage(((dice(1, self.str) if self.str > 0 else 0) + (dice(1, self.weapon_db) if self.weapon_db > 0 else 0)) * self.melee_mult)

if not self.riding:
    self.mp -= lookup(skill_cost, self.ride.level)
self.riding = 0 if self.riding else 1

self.spirit_form = 0 if self.spirit_form else 1
if not self.spirit_form:
    self.riding = 0

presets.bonus:
self.str += 2 if this.level >= 5 else 1  # 狂化：筋力
if this.level >= 2:
    self.con += 1  # 狂化：耐久
if this.level >= 3:
    self.agi += 1  # 狂化：敏捷
if this.level >= 4:
    self.int += 1  # 狂化：魔力
elif this.level <= 2:
    self.int -= 1  # 狂化：魔力
if this.level == 1:
    self.luk -= 1  # 狂化：幸运

presets.script:
if reacting and level >= 1 and level > opp_level:
    self.negate()
    target.damage((dice(self.agi if self.klass == "Assassin" else self.str, lookup(class_melee, self.klass))) * self.melee_mult)

if reacting and level >= 1 and level > opp_level:
    self.negate()
    target.damage((dice(self.rank, 6) + self.troops) * self.melee_mult)
